// ============ CONFIGURATION ============
const API_URL = '/api';

// ============ CART STATE ============
let cart = [];
const CART_KEY = 'fruit_shop_cart';

// ============ UPI PAYMENT ============
const SHOP_UPI_ID = '8270703110@ibl';
const SHOP_UPI_NAME = 'S.L.A Fruit Shop';
let upiPaymentStarted = false;

// ============ SUPERVISOR SIGNATURE (embedded to guarantee PDF output) ============
const SUPERVISOR_SIGNATURE_DATA_URL = 'data:image/png;base64,';

function buildUpiUri() {
    const total = getCartTotal();
    const params = new URLSearchParams();
    params.set('pa', SHOP_UPI_ID);
    params.set('pn', SHOP_UPI_NAME);
    params.set('cu', 'INR');
    if (total > 0) params.set('am', total.toFixed(2));
    params.set('tn', 'S.L.A Fruit Shop Order Payment');
    return 'upi://pay?' + params.toString();
}

function renderUpiQrCode() {
    const container = document.getElementById('upi-qr-code');
    if (!container || typeof qrcode === 'undefined') return;

    const upiUri = buildUpiUri();
    const qr = qrcode(0, 'M');
    qr.addData(upiUri);
    qr.make();

    container.innerHTML = '';
    container.insertAdjacentHTML('beforeend', qr.createSvgTag(4, 2));
}

function launchUpiApp() {
    if (!document.getElementById('upi-qr-code')) return;
    upiPaymentStarted = true;
    window.location.href = buildUpiUri();
}

function initUpiPayment() {
    document.getElementById('upi-qr-code')?.addEventListener('click', launchUpiApp);
    document.getElementById('upi-pay-btn')?.addEventListener('click', launchUpiApp);

    const autoPlaceOrder = () => {
        if (!upiPaymentStarted) return;
        const checkoutModal = document.getElementById('checkout-modal');
        const upiSelected = document.querySelector('input[name="payment-method"]:checked')?.value === 'upi';
        if (!checkoutModal?.classList.contains('active') || !upiSelected) return;

        upiPaymentStarted = false;
        document.getElementById('checkout-form')?.requestSubmit();
    };

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') autoPlaceOrder();
    });
    window.addEventListener('focus', autoPlaceOrder);
}

function loadCart() {
    try { cart = JSON.parse(localStorage.getItem(CART_KEY)) || []; } catch { cart = []; }
    updateCartUI();
}

function saveCart() {
    localStorage.setItem(CART_KEY, JSON.stringify(cart));
    updateCartUI();
}

function addToCart(fruit) {
    const existing = cart.find(item => item.name === fruit.name);
    if (existing) {
        existing.qty += 1;
    } else {
        cart.push({ name: fruit.name, price: fruit.price, unit: fruit.unit, emoji: getFruitEmoji(fruit.name), qty: 1 });
    }
    saveCart();
    showCartFeedback(fruit.name);
}

function removeFromCart(name) {
    cart = cart.filter(item => item.name !== name);
    saveCart();
}

function updateItemQty(name, delta) {
    const item = cart.find(i => i.name === name);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) {
        removeFromCart(name);
    } else {
        saveCart();
    }
}

function getCartTotal() {
    return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function getCartCount() {
    return cart.reduce((sum, item) => sum + item.qty, 0);
}

function getFruitEmoji(name) {
    const emojiMap = {
        'Mango': '🥭', 'Banana': '🍌', 'Guava': '🍈', 'Papaya': '🍑',
        'Pomegranate': '🍎', 'Watermelon': '🍉', 'Coconut': '🥥', 'Jackfruit': '🍈',
        'Lychee': '🍓', 'Jamun': '🫐', 'Amla': '🍏', 'Chikoo': '🍫',
        'Sitaphal': '🍏', 'Mosambi': '🍊', 'Ber': '🫐', 'Bael': '🍈',
        'Kamrakh': '⭐', 'Kokum': '🫐', 'Apple': '🍎', 'Orange': '🍊',
        'Grapes': '🍇', 'Kiwi': '🥝', 'Dragon Fruit': '🐉', 'Avocado': '🥑',
        'Blueberry': '🫐', 'Strawberry': '🍓', 'Cherry': '🍒', 'Pineapple': '🍍',
        'Fig': '🫐', 'Passion Fruit': '🍈'
    };
    return emojiMap[name] || '🍎';
}

function showCartFeedback(name) {
    const btns = document.querySelectorAll(`.add-cart-btn[data-name="${name}"]`);
    btns.forEach(btn => {
        btn.textContent = '✓ ' + I18N.t('card.added');
        btn.classList.add('added');
        setTimeout(() => {
            btn.textContent = '🛒 ' + I18N.t('card.add');
            btn.classList.remove('added');
        }, 1500);
    });
}

function toggleCart() {
    const drawer = document.getElementById('cart-drawer');
    const overlay = document.getElementById('cart-overlay');
    drawer.classList.toggle('open');
    overlay.classList.toggle('active');
    document.body.style.overflow = drawer.classList.contains('open') ? 'hidden' : '';
    if (drawer.classList.contains('open')) renderCartDrawer();
}

function renderCartDrawer() {
    const body = document.getElementById('cart-body');
    const countEl = document.getElementById('cart-item-count');
    const totalEl = document.querySelector('.cart-total strong');
    if (!body) return;

    countEl.textContent = `(${getCartCount()})`;

    if (!cart.length) {
        body.innerHTML = `
            <div class="cart-empty">
                <div class="cart-empty-icon">🛒</div>
                <p>${I18N.t('cart.empty')}</p>
                <p class="cart-empty-sub">${I18N.t('cart.empty.sub')}</p>
            </div>`;
        totalEl.textContent = '₹0';
        return;
    }

    body.innerHTML = cart.map(item => `
        <div class="cart-item">
            <div class="cart-item-icon">${item.emoji}</div>
            <div class="cart-item-info">
                <div class="cart-item-name">${getLocalFruitName(item.name)}</div>
                <div class="cart-item-price">₹${item.price}/${item.unit}</div>
                <div class="cart-item-actions">
                    <button class="cart-qty-btn" onclick="updateItemQty('${item.name}', -1)">−</button>
                    <span class="cart-qty">${item.qty}</span>
                    <button class="cart-qty-btn" onclick="updateItemQty('${item.name}', 1)">+</button>
                </div>
            </div>
            <div class="cart-item-total">
                ₹${item.price * item.qty}
                <button class="cart-item-remove" onclick="removeFromCart('${item.name}')" title="Remove">✕</button>
            </div>
        </div>
    `).join('');

    totalEl.textContent = `₹${getCartTotal()}`;
}

function updateCartUI() {
    const count = getCartCount();
    document.querySelectorAll('.cart-nav-count, .floating-cart-count').forEach(el => {
        el.textContent = count;
        el.classList.toggle('visible', count > 0);
    });
    if (document.getElementById('cart-drawer')?.classList.contains('open')) {
        renderCartDrawer();
    }
}

