// ============ MODAL FRUIT IMAGE (replaced 3D scene) ============
// openModal now sets the <img> src directly — no Three.js needed here.

// ============ VISIBILITY-MANAGED WEBGL SCENES ============
// Lazily creates a WebGL renderer and disposes it when the canvas leaves the
// viewport, capping the number of live GL contexts. Browsers evict the oldest
// WebGL contexts past their per-page limit, which would otherwise blank scenes
// created early (hero, about, first fruit cards). When a scene re-enters view
// it is rebuilt on a fresh canvas element (a lost context cannot be reused).
let liveContexts = 0;
const MAX_CONTEXTS = 12;
const pendingStarts = [];
window.__liveContexts = () => liveContexts;

function initVisibilityScene(canvas, setupFn, updateFn, opts) {
    opts = opts || {};
    const rootMargin = opts.rootMargin || '250px';

    let renderer = null;
    let rafId = 0;
    let current = canvas;
    let everStarted = false;
    let scene = null;
    let camera = null;
    let io = null;
    let queued = false;
    let cw = 0;
    let ch = 0;

    function createRenderer() {
        cw = current.clientWidth || 300;
        ch = current.clientHeight || 200;
        if (everStarted) {
            const fresh = document.createElement('canvas');
            fresh.className = current.className;
            for (const attr of Array.from(current.attributes)) {
                if (attr.name === 'class' || attr.name === 'id') continue;
                fresh.setAttribute(attr.name, attr.value);
            }
            if (current.id) fresh.id = current.id;
            if (current.style && current.style.cssText) fresh.style.cssText = current.style.cssText;
            if (current.parentNode) current.parentNode.replaceChild(fresh, current);
            if (io) io.unobserve(current);
            current = fresh;
            if (io) io.observe(current);
        }
        everStarted = true;
        renderer = new THREE.WebGLRenderer({ canvas: current, antialias: true, alpha: true });
        renderer.setSize(cw, ch);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }

    function start() {
        if (renderer) return;
        if (liveContexts >= MAX_CONTEXTS) {
            queued = true;
            if (pendingStarts.indexOf(start) === -1) pendingStarts.push(start);
            return;
        }
        queued = false;
        liveContexts++;
        createRenderer();
        if (!scene) {
            const built = setupFn(current, renderer);
            scene = built.scene;
            camera = built.camera;
        }
        camera.aspect = cw / ch;
        camera.updateProjectionMatrix();
        if (opts.onStart) opts.onStart(renderer, current);
        const loop = () => {
            rafId = requestAnimationFrame(loop);
            updateFn(current, renderer, scene, camera, Date.now() * 0.001);
            if (renderer) {
                try {
                    renderer.render(scene, camera);
                } catch (err) { /* context may have been reclaimed mid-frame */ }
            }
        };
        loop();
    }

    function stop() {
        if (rafId) cancelAnimationFrame(rafId);
        rafId = 0;
        if (renderer) {
            renderer.dispose();
            renderer.forceContextLoss();
            renderer = null;
            liveContexts = Math.max(0, liveContexts - 1);
            if (opts.onStop) opts.onStop();
            drainQueue();
        } else if (queued) {
            const i = pendingStarts.indexOf(start);
            if (i !== -1) pendingStarts.splice(i, 1);
            queued = false;
        }
    }

    function drainQueue() {
        while (pendingStarts.length && liveContexts < MAX_CONTEXTS) {
            const fn = pendingStarts.shift();
            fn();
        }
    }

    if ('IntersectionObserver' in window) {
        io = new IntersectionObserver((entries) => {
            entries.forEach(en => {
                if (en.isIntersecting) {
                    start();
                } else {
                    stop();
                }
            });
        }, { rootMargin });
        io.observe(current);
    } else {
        start();
    }
}

// ============ MINI FRUIT SCENE ============
function initMiniScene(canvas, fruitName, color, opts) {
    if (!canvas) return;

    opts = opts || {};
    const target = opts.target || 1.5;
    const cameraZ = opts.cameraZ || 2.2;
    const phase = Math.random() * Math.PI * 2;

    initVisibilityScene(canvas, () => {
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(60, 1, 0.1, 1000);
        camera.position.z = cameraZ;

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
        keyLight.position.set(3, 4, 3.5);
        scene.add(keyLight);

        const fillLight = new THREE.DirectionalLight(0xbfd9ff, 0.4);
        fillLight.position.set(-3, 1, -2);
        scene.add(fillLight);

        const bounceLight = new THREE.DirectionalLight(0xffe8cc, 0.35);
        bounceLight.position.set(1, -2, 1);
        scene.add(bounceLight);

        let fruit;
        try {
            fruit = createFruitModel(fruitName);
        } catch (err) {
            fruit = new THREE.Mesh(new THREE.SphereGeometry(0.6, 20, 16), new THREE.MeshPhongMaterial({ color: color || 0xFF0000, shininess: 60 }));
        }

        const box = new THREE.Box3().setFromObject(fruit);
        const size = box.getSize(new THREE.Vector3());
        const maxDim = Math.max(size.x, size.y, size.z) || 1;
        const s = target / maxDim;
        fruit.scale.multiplyScalar(s);

        const center = box.getCenter(new THREE.Vector3());
        const baseY = -center.y * s;
        fruit.position.set(-center.x * s, baseY, -center.z * s);
        fruit.rotation.y = 0.6;
        fruit.rotation.x = 0.12;
        scene.add(fruit);

        scene.userData.baseY = baseY;
        scene.userData.fruit = fruit;
        return { scene, camera };
    }, (cv, r, scene, camera, t) => {
        const fruit = scene.userData.fruit;
        fruit.rotation.y += 0.008;
        fruit.position.y = scene.userData.baseY + Math.sin(t * 1.6 + phase) * 0.06;
    });
}

// ============ API & FRUITS ============
function fetchFruits() {
    displaySampleFruits();
}

let currentFruits = [];

function displayFruits(fruits) {
    currentFruits = fruits;
    const indianContainer = document.getElementById('indian-fruits');
    const foreignContainer = document.getElementById('foreign-fruits');
    const bestsellerContainer = document.getElementById('bestseller-fruits');
    if (!indianContainer || !foreignContainer) return;

    indianContainer.innerHTML = '';
    foreignContainer.innerHTML = '';
    if (bestsellerContainer) bestsellerContainer.innerHTML = '';

    fruits.forEach((fruit, index) => {
        const card = createFruitCard(fruit);
        card.style.animationDelay = `${index * 0.05}s`;
        if (fruit.category === 'indian') {
            indianContainer.appendChild(card);
        } else {
            foreignContainer.appendChild(card);
        }
        observeReveal(card);
        if (bestsellerContainer && fruit.bestseller) {
            const bsCard = card.cloneNode(true);
            bestsellerContainer.appendChild(bsCard);
            observeReveal(bsCard);
        }
    });

    // Initialize mini 3D scenes
    setTimeout(() => {
        document.querySelectorAll('.card-canvas').forEach(canvas => {
            const name = canvas.dataset.fruit;
            const color = parseInt(canvas.dataset.color);
            initMiniScene(canvas, name, color);
        });
    }, 200);
}

function createFruitCard(fruit) {
    const card = document.createElement('div');
    card.className = 'fruit-card reveal';
    card.dataset.season = fruit.season;
    if (fruit.origin) card.dataset.origin = fruit.origin;

    const color = fruitColors[fruit.name] || 0xFF0000;
    const categoryLabel = fruit.category === 'indian' ? '🇮🇳 ' + (I18N.t('card.indian')) : '🌍 ' + (I18N.t('card.imported'));
    const healthTags = fruit.health ? fruit.health.slice(0, 2).map(h => `<span class="health-tag">${I18N.benefit(h)}</span>`).join('') : '';
    const photoSlug = slugify(fruit.name);
    const photoSrc = fruit.image || 'images/' + photoSlug + '.jpg';
    const webpSrc = 'images/' + photoSlug + '.webp';
    const subName = getFruitSubName(fruit.name);

    card.innerHTML = `
        <div class="fruit-card-canvas" style="background: linear-gradient(135deg, ${hexColor(color)}33 0%, ${darkenColor(color, 0.3)}44 100%)">
            ${fruit.bestseller ? `<span class="bestseller-badge"><span class="bestseller-star">★</span> ${I18N.t('bestseller.badge')}</span>` : ''}
            <span class="card-emoji-fallback">${getFruitEmoji(fruit.name)}</span>
            <picture>
                <source srcset="${webpSrc}" type="image/webp">
                <img class="card-photo card-photo-visible" src="${photoSrc}" alt="${fruit.name}" loading="lazy" width="800" height="800" onerror="this.onerror=null; this.style.display='none'; const fb=this.parentNode.querySelector('.card-emoji-fallback'); if(fb) fb.style.display='flex';">
            </picture>
        </div>
        <div class="fruit-card-info">
            <span class="modal-category">${categoryLabel}</span>
            <h3>${getLocalFruitName(fruit.name)}</h3>
            ${subName ? `<span class="fruit-tamil-name">${subName}</span>` : ''}
            <p>${I18N.fruitDesc(fruit.name) || fruit.description}</p>
            <div class="health-tags">${healthTags}</div>
            ${fruit.region ? `<span class="fruit-region">📍 ${fruit.region}</span>` : ''}
            <div class="fruit-price">
                <span class="price">₹${fruit.price}/${fruit.unit}</span>
                <div class="fruit-actions">
                    <button class="view-btn" data-fruit='${JSON.stringify(fruit).replace(/'/g, "&#39;")}'>${I18N.t('card.view')}</button>
                    <button class="add-cart-btn" data-name="${fruit.name}" data-price="${fruit.price}" data-unit="${fruit.unit}">🛒 ${I18N.t('card.add')}</button>
                </div>
            </div>
        </div>
    `;

    return card;
}

