// ============ HELPER FUNCTIONS ============
function slugify(name) {
    return String(name).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function hexColor(color) {
    return '#' + color.toString(16).padStart(6, '0');
}

function darkenColor(color, amount) {
    const r = Math.max(0, Math.floor((color >> 16) * (1 - amount)));
    const g = Math.max(0, Math.floor(((color >> 8) & 0xFF) * (1 - amount)));
    const b = Math.max(0, Math.floor((color & 0xFF) * (1 - amount)));
    return `rgb(${r}, ${g}, ${b})`;
}

// ============ MODAL ============
function openModal(fruitData) {
    const modal = document.getElementById('fruit-modal');
    if (!modal) return;

    modal.classList.add('active');
    document.body.style.overflow = 'hidden';

    const imgEl = document.getElementById('modal-fruit-img');
    if (imgEl) {
        const slug = slugify(fruitData.name);
        imgEl.src = 'images/' + slug + '.webp';
        imgEl.alt = fruitData.name;
        imgEl.onerror = function() { this.onerror = null; this.src = 'images/' + slug + '.jpg'; };
    }

    const catEl = document.getElementById('modal-fruit-category');
    const nameEl = document.getElementById('modal-fruit-name');
    const descEl = document.getElementById('modal-fruit-desc');
    const priceEl = document.getElementById('modal-fruit-price');
    const unitEl = document.getElementById('modal-fruit-unit');
    const originEl = document.getElementById('modal-fruit-origin');
    const seasonEl = document.getElementById('modal-fruit-season');
    const healthEl = document.getElementById('modal-health-benefits');
    const nutritionEl = document.getElementById('modal-nutrition');

    if (catEl) catEl.textContent = fruitData.category === 'indian' ? '🇮🇳 ' + I18N.t('modal.cat.indian') : '🌍 ' + I18N.t('modal.cat.imported');
    if (nameEl) {
        nameEl.textContent = getLocalFruitName(fruitData.name);
        const subName = getFruitSubName(fruitData.name);
        if (subName) nameEl.textContent += ` · ${subName}`;
    }
    if (descEl) descEl.textContent = I18N.fruitDesc(fruitData.name) || fruitData.description;
    if (priceEl) priceEl.textContent = fruitData.price;
    if (unitEl) unitEl.textContent = fruitData.unit;
    if (originEl) originEl.textContent = fruitData.origin;
    if (seasonEl) seasonEl.textContent = fruitData.season;

    if (healthEl) {
        const hList = (I18N.healthList(fruitData.name) || (fruitData.health || []).map(h => I18N.benefit(h)));
        if (hList.length) healthEl.innerHTML = hList.map(h => `<span class="health-badge">✨ ${h}</span>`).join('');
    }

    if (nutritionEl && fruitData.nutrition) {
        const n = fruitData.nutrition;
        const maxVals = { calories: 100, vitaminC: 600, vitaminA: 60, fiber: 10 };
        nutritionEl.innerHTML = `
            <h4 class="nutrition-title">🥗 ${I18N.t('modal.nutrition')}</h4>
            <div class="nutrition-bars">
                ${n.calories ? `<div class="nutri-item"><span class="nutri-label">${I18N.t('nutri.calories')}</span><div class="nutri-bar"><div class="nutri-fill" style="width:${(n.calories/maxVals.calories)*100}%"></div></div><span class="nutri-val">${n.calories} kcal</span></div>` : ''}
                ${n.vitaminC !== undefined ? `<div class="nutri-item"><span class="nutri-label">${I18N.t('nutri.vitc')}</span><div class="nutri-bar"><div class="nutri-fill fill-vitc" style="width:${(n.vitaminC/maxVals.vitaminC)*100}%"></div></div><span class="nutri-val">${n.vitaminC} mg</span></div>` : ''}
                ${n.vitaminA !== undefined ? `<div class="nutri-item"><span class="nutri-label">${I18N.t('nutri.vita')}</span><div class="nutri-bar"><div class="nutri-fill fill-vita" style="width:${(n.vitaminA/maxVals.vitaminA)*100}%"></div></div><span class="nutri-val">${n.vitaminA} µg</span></div>` : ''}
                ${n.fiber !== undefined ? `<div class="nutri-item"><span class="nutri-label">${I18N.t('nutri.fiber')}</span><div class="nutri-bar"><div class="nutri-fill fill-fiber" style="width:${(n.fiber/maxVals.fiber)*100}%"></div></div><span class="nutri-val">${n.fiber} g</span></div>` : ''}
            </div>
        `;
    }
}

