function renderSeasonalCalendar() {
    const container = document.getElementById('calendar-months');
    if (!container) return;

    // Header row
    let html = `<div class="calendar-row"><div class="calendar-label">${I18N.t('calendar.fruits')}</div>`;
    seasonalMonths.forEach((m, i) => {
        html += `<div class="calendar-month-label">${I18N.month(i)}</div>`;
    });
    html += '</div>';

    // Fruit rows
    seasonalFruits.forEach(fruit => {
        html += `<div class="calendar-row">`;
        html += `<div class="calendar-label">${getLocalFruitName(fruit.name)}</div>`;
        for (let m = 0; m < 12; m++) {
            const isPeak = fruit.season.includes(m);
            const isOffSeason = !isPeak;
            // Show adjacent months as "available"
            const isAvailable = fruit.season.includes(m - 1) || fruit.season.includes(m + 1);
            let dotClass = 'off';
            if (isPeak) dotClass = 'peak';
            else if (isAvailable && fruit.season.length < 12) dotClass = 'available';
            html += `<div class="calendar-dots"><div class="calendar-dot ${dotClass}"></div></div>`;
        }
        html += `</div>`;
    });

    container.innerHTML = html;
}

// ============ TYPEWRITER EFFECT ============
let typewriterPhrases = [];

function initTypewriter() {
    const el = document.querySelector('.hero-desc');
    if (!el) return;

    const phrases = I18N.tList('hero.typewriter');
    typewriterPhrases = phrases.length ? phrases : [
        'Premium collection of 27+ Indian & imported fruits',
        'Fresh mangoes from Maharashtra\'s Alphonso orchards',
        'Juicy pomegranates from Andhra Pradesh',
        'Sweet lychees from Bihar & West Bengal',
        'Farm-fresh delivery to your doorstep 🚚'
    ];
    let phraseIdx = 0;
    let charIdx = 0;
    let isDeleting = false;
    let isPaused = false;

    function type() {
        const current = typewriterPhrases[phraseIdx] || phrases[phraseIdx] || '';
        if (isPaused) {
            isPaused = false;
            isDeleting = true;
            setTimeout(type, 50);
            return;
        }
        if (!isDeleting) {
            charIdx++;
            el.textContent = current.substring(0, charIdx);
            if (charIdx === current.length) {
                isPaused = true;
                setTimeout(type, 2000);
                return;
            }
            setTimeout(type, 40 + Math.random() * 30);
        } else {
            charIdx--;
            el.textContent = current.substring(0, charIdx);
            if (charIdx === 0) {
                isDeleting = false;
                phraseIdx = (phraseIdx + 1) % phrases.length;
                setTimeout(type, 300);
                return;
            }
            setTimeout(type, 20 + Math.random() * 20);
        }
    }

    setTimeout(type, 2500);
}

// ============ BUBBLE CARDS ============
function initBubbleCards() {
    const cards = document.querySelectorAll('.floating-card');
    if (!cards.length) return;

    const params = [];
    cards.forEach(() => {
        params.push({
            speedX: 0.15 + Math.random() * 0.25,
            speedY: 0.12 + Math.random() * 0.2,
            phaseX: Math.random() * Math.PI * 2,
            phaseY: Math.random() * Math.PI * 2,
            ampX: 25 + Math.random() * 35,
            ampY: 20 + Math.random() * 30,
            driftSpeed: 0.03 + Math.random() * 0.05,
            driftPhase: Math.random() * Math.PI * 2,
            driftAmp: 15 + Math.random() * 25,
            wobble: 2 + Math.random() * 4,
            wobbleSpeed: 0.8 + Math.random() * 1.2,
            rotAmp: 2 + Math.random() * 3,
            rotSpeed: 0.1 + Math.random() * 0.15,
            hovered: false
        });
    });

    cards.forEach((card, i) => {
        card.addEventListener('mouseenter', () => { params[i].hovered = true; });
        card.addEventListener('mouseleave', () => { params[i].hovered = false; });
    });

    function animateBubbles() {
        const time = Date.now() * 0.001;

        cards.forEach((card, i) => {
            const p = params[i];

            const x = Math.sin(time * p.speedX + p.phaseX) * p.ampX
                    + Math.sin(time * p.driftSpeed + p.driftPhase) * p.driftAmp
                    + Math.sin(time * p.wobbleSpeed + p.phaseY) * p.wobble;

            const y = Math.cos(time * p.speedY + p.phaseY) * p.ampY
                    + Math.cos(time * p.driftSpeed * 0.7 + p.driftPhase + 1) * p.driftAmp * 0.6
                    + Math.cos(time * p.wobbleSpeed * 0.8 + p.phaseX) * p.wobble;

            const rot = Math.sin(time * p.rotSpeed + p.phaseX) * p.rotAmp;

            const scale = p.hovered ? 1.05 : 1;

            card.style.setProperty('--bx', x + 'px');
            card.style.setProperty('--by', y + 'px');
            card.style.setProperty('--br', rot + 'deg');
            card.style.setProperty('--bs', scale);
        });

        requestAnimationFrame(animateBubbles);
    }

    animateBubbles();
}

