    // Pick up URL params on page load:
    //  - a completed social login (?authToken=&authUser=...) or an error (?authError=&authMessage=...)
    (function handleAuthRedirects() {
        const params = new URLSearchParams(window.location.search);
        const authToken = params.get('authToken');
        const authUser = params.get('authUser');
        const authError = params.get('authError');
        const authMessage = params.get('authMessage');

        if (authToken && authUser) {
            // URLSearchParams already decodes the payload, so storing it raw is
            // correct. The previous extra decodeURIComponent() threw for any
            // name/email containing "%", which silently skipped the whole login.
            try { localStorage.setItem('token', authToken); } catch (err) { /* ignore */ }
            try { localStorage.setItem('user', authUser); } catch (err) { /* ignore */ }
            updateUserUI();
        }

        if (authError) {
            console.error('Social login failed:', authError, authMessage || '');
            // Surface the failure in the sign-in form instead of silently
            // landing on the homepage still "not logged in".
            const signInErrorEl = document.getElementById('signin-error');
            if (signInErrorEl) {
                signInErrorEl.textContent = authMessage
                    ? `Couldn't sign in with ${authError}: ${authMessage}. Please try again.`
                    : `Couldn't sign in with ${authError}. Please try again.`;
                const modal = document.getElementById('auth-modal');
                if (modal) {
                    modal.classList.add('active');
                    document.body.style.overflow = 'hidden';
                    document.querySelectorAll('.auth-tab').forEach(t => t.classList.remove('active'));
                    document.querySelectorAll('.auth-form').forEach(f => f.classList.remove('active'));
                    const signInTab = document.querySelector('.auth-tab[data-tab="signin"]');
                    if (signInTab) signInTab.classList.add('active');
                    document.getElementById('signin-form')?.classList.add('active');
                }
            }
        }

        if (authToken || authError) {
            const url = new URL(window.location.href);
            ['authToken', 'authUser', 'authError', 'authMessage'].forEach(p => url.searchParams.delete(p));
            window.history.replaceState({}, document.title, url.pathname + url.hash);
        }
    })();

